const enabled = $env.DAX_ENABLE_PUBLIC_PUBLISHING === 'true';
const approvedValues = ['approved_for_publish', 'approved', 'ready_to_publish'];
return $input.all().filter((item) => {
  const data = item.json || {};
  const approved = data.approvedForPublish === true || approvedValues.includes(data.reviewStatus) || approvedValues.includes(data.review_status) || approvedValues.includes(data.approvalStatus);
  return enabled && approved;
}).map((item) => {
  item.json.daxPublishingGuard = { passed: true, checkedAt: new Date().toISOString(), targetNode: 'Publish Travel Blog' };
  return item;
});

